package catalog
import "testing"
func TestWebSearchSelectionAndRequiredRelease(t *testing.T){if DefaultInstall("websearch")||CategoryFor("websearch").ID!="administration"{t.Fatal("optional service policy")};c:=Catalog{Packages:map[string]Package{"websearch":{},"websearch-runtime-browser":{},"websearch-runtime-llama":{}},Apps:[]App{{ID:"websearch",Package:"websearch"}}};for _,on:=range []bool{false,true}{keep:=InstallPackageIDs(c,map[string]bool{"websearch":on});for _,id:=range []string{"websearch","websearch-runtime-browser","websearch-runtime-llama"}{if keep[id]!=on{t.Fatal("runtime selection split")}}};full:=Catalog{};for _,a:=range ManagedApps(){if a.ID!="websearch"{full.Apps=append(full.Apps,App{ID:a.ID,Name:a.Name,Route:a.Route,OIDC:a.OIDC})}};if full.ValidateManagedInventory()==nil{t.Fatal("release omitted Web Search")}}
